function list() { uni.reLaunch({ url: '/pages/exam/index' }) }
const rules = ['倒计时以服务端截止时间为准，刷新或切后台不会暂停。', '答案自动保存为本人草稿，可在答题卡中随时跳题。', '时间到将锁定作答，未成功交卷按超时处理，不再接受提交。', '交卷后不可修改，客观题由系统自动评分。']
</script>
