  <AppPage title="考试须知"><view class="paper-intro"><text class="paper-intro__eyebrow">PAPER · NO.0016</text><text class="paper-intro__title">{{ examTitle }}</text><text class="paper-intro__description">依据出题资料《消防安全培训讲义》v3 生成，覆盖疏散、灭火器使用与火灾报警流程。</text><view class="paper-metrics"><view v-for="metric in [{ value: 30, unit: '分钟', label: '时长' }, { value: 20, unit: '道', label: '题量' }, { value: 60, unit: '分', label: '及格' }]" :key="metric.label"><text class="paper-metrics__value">{{ metric.value }}</text><text>{{ metric.unit }}</text><text class="paper-metrics__label">{{ metric.label }}</text></view></view></view>
    <view class="paper-section"><text class="paper-section__title">题型构成</text><view v-for="row in [{ title: '单选题', count: '10 题 × 5 分', score: 50 }, { title: '多选题', count: '5 题 × 6 分', score: 30 }, { title: '判断题', count: '5 题 × 4 分', score: 20 }]" :key="row.title" class="paper-type"><text>{{ row.title }}</text><text>{{ row.count }}</text><text>{{ row.score }} 分</text></view></view>
    <view class="paper-section"><text class="paper-section__title">考试规则</text><view v-for="(rule, index) in rules" :key="rule" class="paper-rule"><text>{{ String(index + 1).padStart(2, '0') }}</text><text>{{ rule }}</text></view></view>
    <view class="paper-footer"><wd-button block @click="start">开始答题</wd-button><text>剩余可考 2 次 · 开始后计时不可暂停</text></view>
    <wd-popup v-model="showDraft" position="center" round :close-on-click-modal="false" custom-style="width: calc(100% - 48px); max-width: 366px"><view class="draft-dialog"><text class="draft-dialog__title">{{ scenario.overlay === 'recover' ? '发现未完成的答题' : '本地草稿无法恢复' }}</text><text>{{ scenario.overlay === 'recover' ? '上次作答于 10-21 14:06，已答 6 / 20 题。考试截止时间不会因重新开始而延长。' : '草稿与当前试卷版本不一致或已损坏，已忽略这份草稿。服务端已保存的作答状态和截止时间不受影响。' }}</text><text v-if="scenario.overlay === 'recover'" class="draft-dialog__remaining">剩余 18:42</text><view v-else class="draft-dialog__reasons"><text>题目版本已更新</text><text>草稿数据损坏</text><text>考试已截止（将查询结果）</text></view><view class="draft-dialog__actions"><wd-button variant="soft" @click="scenario.overlay === 'recover' ? start() : list()">{{ scenario.overlay === 'recover' ? '重新开始' : '返回列表' }}</wd-button><wd-button @click="start">{{ scenario.overlay === 'recover' ? '恢复答题' : '继续作答' }}</wd-button></view></view></wd-popup>
  </AppPage>
</template>
